def test_actual_four_head_200_step_scalar_batch_parity(trained):
    cases, scalar = trained
    batch = learning.fit_pipeline(cases, 0.001, backend="batch")
    for name, left, right in [("Q", scalar.q, batch.q)] + [
        (arm, scalar.residuals[arm], batch.residuals[arm]) for arm in learning.RESIDUAL_ARMS
    ]:
        assert len(left.trace) == len(right.trace) == 200
        assert max(row["gradient_norm"] for row in right.trace) > 1e-12
        assert np.max(np.abs(right.coefficients)) > 1e-12
        np.testing.assert_allclose(left.coefficients, right.coefficients, atol=1e-8, rtol=0)
        np.testing.assert_allclose(left.final_loss, right.final_loss, atol=1e-8, rtol=0)
        # No artificial efficacy ordering is required among the four heads.
        a, b = learning.predict(scalar, cases, name), learning.predict(batch, cases, name)
        for key in a:
            np.testing.assert_allclose(a[key], b[key], atol=1e-8, rtol=0)
            np.testing.assert_array_equal(a[key].argmax(-1), b[key].argmax(-1))


def mixed_cases():
    rng = np.random.default_rng(73)
    cases = []
    for pid in (12001, 12002):
        packet = rng.uniform(0, 30, (5, 8))
        packet[:, 2] = np.nan
        for samples in (17, 23):
            proto = rng.normal(size=(12, 5, 8, samples)) + 0.7
            support = proto[None] + rng.normal(size=(5, 12, 5, 8, samples))
            source = proto + rng.normal(size=proto.shape)
            for k in (3, 5):
                cases.append(
                    learning.make_task_case(
                        pid,
                        0,
                        0,
                        support[:k],
                        packet[:k],
                        np.linspace(9, 14.5, 12),
                        source,
                        weights=np.linspace(1.3, 0.4, 5) * (1 + k / 20),
                        labels=np.roll(np.arange(12), pid % 12),
                    )
                )
    return tuple(cases)


def test_mixed_windows_budgets_unsorted_batch_loss_and_gradient():
    cases = tuple(reversed(mixed_cases()))
    logits = torch.linspace(-0.2, 0.2, len(cases) * 40, dtype=torch.float64).reshape(-1, 5, 8)
    logits.requires_grad_()
    batch = TaskBatch(cases)
    actual = batch.scores(logits)
    expected = torch.stack([learning._prior_scores(c, logits[j]) for j, c in enumerate(cases)])
    torch.testing.assert_close(actual, expected, atol=1e-8, rtol=0)
    loss = batch.loss(logits)
    reference = torch.stack([learning._ce(expected[j], c) for j, c in enumerate(cases)]).mean()
    ga = torch.autograd.grad(loss, logits, retain_graph=True)[0]
    gr = torch.autograd.grad(reference, logits)[0]
    torch.testing.assert_close(loss, reference, atol=1e-8, rtol=0)
    torch.testing.assert_close(ga, gr, atol=1e-8, rtol=0)
    assert ga.abs().max() > 1e-12
    assert batch.samples == tuple(c.samples for c in cases)
    assert set(batch.stats) == {"query_gram", "template_gram", "cross_gram"}


def test_nested_packet_prefix_and_batch_case_geometry():
    cases = mixed_cases()
    bad = cases[0]
    packet = np.array(bad.packet) + 1
    m, available = learning.features.metadata_features(packet)
    bad = replace(
        bad,
        packet=learning._readonly(packet),
        m=learning._readonly(m),
        available=learning._readonly(available, bool),
    )
    with pytest.raises(ValueError, match="Metadata identity"):
        TaskBatch((bad, *cases[1:]))
    # Change BOTH windows at k=3, so only the nested k=3/k=5 identity fails.
    altered = []
    for case in cases:
        if case.participant_id == bad.participant_id and case.k == 3:
            altered.append(replace(case, packet=bad.packet, m=bad.m, available=bad.available))
        else:
            altered.append(case)
    with pytest.raises(ValueError, match="prefix"):
        TaskBatch(altered)
    with pytest.raises(ValueError, match="sample counts"):
        replace(cases[0], samples=19)
    with pytest.raises(ValueError, match="common grid"):
        TaskBatch(cases[:-1])


