def test_n1_original_inputs_exact_tau_and_detached_diagnostics(trained):
    case = trained[0][0]
    logits = torch.linspace(-0.2, 0.2, 40, dtype=torch.float64).reshape(5, 8).requires_grad_()
    r = learning.operator.shape_prior(logits)
    f = signfree.bounded_projectors(case.s, case.c, r[:, None])
    tau = 0.1 * torch.linalg.eigvalsh((case.c + case.c.mT) / 2)[..., 0] / (16 / 9)
    b = case.c + torch.diag_embed(tau[..., None] * r[:, None])
    expected = signfree.numerical.projector(case.s, b, case.c, "N1_SYM_CHOLESKY")
    torch.testing.assert_close(f, expected, atol=0, rtol=0)
    info = signfree.diagnostics(case.s, case.c, r[:, None], f)
    assert set(info) == {
        "lambda",
        "residual",
        "normalization_error",
        "symmetry_error",
        "raw_h_skew",
        "normalization_ratio",
    }
    assert all(not value.requires_grad and torch.isfinite(value).all() for value in info.values())
    assert (info["residual"] <= 1e-12).all()
    assert (info["normalization_ratio"] >= 1 / 1.1 - 1e-10).all()
    scores = signfree.score_temporal_gram(f, case.statistics, case.weights)[0]
    gradient = torch.autograd.grad(learning._ce(scores, case), logits)[0]
    assert gradient.abs().max() > 1e-12
    # Same forward values with a detached F cannot satisfy the gradient oracle.
    detached = signfree.score_temporal_gram(f.detach(), case.statistics, case.weights)[0]
    wrong = learning._ce(detached, case) + logits.sum() * 0
    wrong_gradient = torch.autograd.grad(wrong, logits)[0]
    assert torch.count_nonzero(wrong_gradient) == 0
    assert not torch.allclose(gradient, wrong_gradient, atol=1e-12, rtol=0)


@pytest.mark.parametrize(
    "bad", ["s_skew", "c_skew", "finite", "spd", "gap", "live_s", "live_c", "prior", "broadcast"]
)
def test_n1_adapter_guards(bad):
    c = torch.eye(8, dtype=torch.float64)
    s = torch.diag(torch.arange(8, dtype=torch.float64))
    r = torch.ones(8, dtype=torch.float64)
    if bad == "s_skew":
        s *= 1e-8
        s[0, 1] = 1e-13  # Old max(norm,1) would hide this; N1 must reject.
    elif bad == "c_skew":
        c *= 1e-8
        c[0, 1] = 1e-13
    elif bad == "finite":
        s[0, 0] = torch.nan
    elif bad == "spd":
        c[0, 0] = 0
    elif bad == "gap":
        s = c.clone()
    elif bad == "live_s":
        s.requires_grad_()
    elif bad == "live_c":
        c.requires_grad_()
    elif bad == "prior":
        r[0] = 2
    elif bad == "broadcast":
        r = torch.ones(2, 8, dtype=torch.float64)
    with pytest.raises(ValueError):
        signfree.bounded_projectors(s, c, r)


def test_normalization_bound_sensitivity():
    c = torch.eye(8, dtype=torch.float64)
    f = c / 8
    with pytest.raises(ValueError, match="bounded-denominator"):
        signfree._normalization_ratio(c, 2 * c, f)
    with pytest.raises(ValueError, match="positive"):
        signfree._normalization_ratio(c, -c, f)


def test_accepted_tiny_raw_skew_is_preserved_in_denominator():
    c = torch.eye(8, dtype=torch.float64)
    c[0, 1] = 1e-14
    s = torch.diag(torch.arange(8, dtype=torch.float64))
    r = torch.ones(8, dtype=torch.float64)
    b = signfree._denominator(s, c, r)
    assert b[0, 1] == c[0, 1] and b[1, 0] == c[1, 0]
    assert b[0, 1] != b[1, 0]
    f = signfree.bounded_projectors(s, c, r)
    info = signfree.diagnostics(s, c, r, f)
    assert (info["residual"] <= 1e-12).all()


def test_scalar_batch_native_anchors_do_not_change_gradient(trained):
    cases = trained[0]
    altered = tuple(replace(c, anchors=torch.zeros_like(c.anchors)) for c in cases)
    logits = torch.linspace(-0.2, 0.2, len(cases) * 40, dtype=torch.float64).reshape(-1, 5, 8)
    logits.requires_grad_()
    left, right = TaskBatch(cases), TaskBatch(altered)
    torch.testing.assert_close(left.scores(logits), right.scores(logits), atol=0, rtol=0)
    ga = torch.autograd.grad(left.loss(logits), logits)[0]
    gb = torch.autograd.grad(right.loss(logits), logits)[0]
    torch.testing.assert_close(ga, gb, atol=0, rtol=0)


@pytest.mark.parametrize("bad", ["shape", "dtype", "finite", "bounds"])
def test_batch_bad_logits_rejected(trained, bad):
    batch = TaskBatch(trained[0])
    logits = torch.zeros(batch.cases, 5, 8, dtype=torch.float64)
    if bad == "shape":
        logits = logits[:1]
    elif bad == "dtype":
        logits = logits.float()
    elif bad == "finite":
        logits[0, 0, 0] = torch.nan
    else:
        logits[0, 0, 0] = 1
    with pytest.raises(ValueError):
        batch.scores(logits)


def test_batch_zero_projected_variance_remains_a_failure(trained):
    case = trained[0][0]
    zero = replace(case.statistics, query_gram=torch.zeros_like(case.statistics.query_gram))
    with pytest.raises(ValueError, match="variance"):
        TaskBatch((replace(case, statistics=zero),))
